import { useState, useEffect, useCallback, useMemo } from 'react';
import { Table, Button, Modal, Form, Input, Upload, Select, Space, Popconfirm, message, Typography, Tag } from 'antd';
import {
  DeleteOutlined, DownloadOutlined, UploadOutlined, SaveOutlined,
  FileTextOutlined, FolderOpenOutlined, PaperClipOutlined,
  EditOutlined, EyeOutlined, PrinterOutlined, SearchOutlined, FilterOutlined,
} from '@ant-design/icons';
import { createCrudApi, fileApi } from '../api/client';
import { PageHeader } from '../components/PageHeader';
import { AppModal } from '../components/AppModal';

const { Title, Text } = Typography;

const templatesApi = createCrudApi('/templates');

// استخراج صيغة الملف من اسم الملف
const getFileFormat = (fileName: string): string => {
  if (!fileName) return '-';
  const parts = fileName.split('.');
  if (parts.length < 2) return '-';
  const ext = parts[parts.length - 1].toUpperCase();
  return ext;
};

// لون التاج حسب الصيغة
const formatColor = (ext: string): string => {
  const map: Record<string, string> = {
    'PDF': '#c0392b',
    'DOC': '#2980b9', 'DOCX': '#2980b9',
    'XLS': '#27ae60', 'XLSX': '#27ae60',
    'PPT': '#e67e22', 'PPTX': '#e67e22',
    'JPG': '#8e44ad', 'JPEG': '#8e44ad', 'PNG': '#8e44ad', 'GIF': '#8e44ad',
    'TXT': '#7f8c8d',
    'ZIP': '#d35400', 'RAR': '#d35400',
  };
  return map[ext] || '#2c3e50';
};

export default function Templates() {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [form] = Form.useForm();
  const [uploading, setUploading] = useState(false);
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string | undefined>(undefined);
  const [formatFilter, setFormatFilter] = useState<string | undefined>(undefined);

  const [printing, setPrinting] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try { const res = await templatesApi.getAll(); setData(res.data.data || res.data || []); }
    catch { message.error('حدث خطأ'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  // استخراج التصنيفات الفريدة من البيانات
  const categoryOptions = useMemo(() => {
    const cats = new Set<string>();
    data.forEach((d: any) => { if (d.category) cats.add(d.category); });
    return Array.from(cats).map((c) => ({ value: c, label: c }));
  }, [data]);

  // استخراج الصيغ الفريدة من البيانات
  const formatOptions = useMemo(() => {
    const fmts = new Set<string>();
    data.forEach((d: any) => { const f = getFileFormat(d.fileName); if (f !== '-') fmts.add(f); });
    return Array.from(fmts).map((f) => ({ value: f, label: f }));
  }, [data]);

  // تصفية البيانات
  const filtered = useMemo(() => {
    return data.filter((item: any) => {
      // فلتر البحث
      if (search) {
        const q = search.toLowerCase();
        if (!(item.title || '').toLowerCase().includes(q) && !(item.category || '').toLowerCase().includes(q)) return false;
      }
      // فلتر التصنيف
      if (categoryFilter && item.category !== categoryFilter) return false;
      // فلتر الصيغة
      if (formatFilter) {
        const fmt = getFileFormat(item.fileName);
        if (fmt !== formatFilter) return false;
      }
      return true;
    });
  }, [data, search, categoryFilter, formatFilter]);

  const openAdd = () => {
    setEditing(null);
    form.resetFields();
    setModalOpen(true);
  };

  const openEdit = (record: any) => {
    setEditing(record);
    form.setFieldsValue(record);
    setModalOpen(true);
  };

  const handleSubmit = async () => {
    try {
      const values = await form.validateFields();
      setUploading(true);

      if (editing?._id) {
        let fileId = editing.fileId;
        let fileName = editing.fileName;
        if (values.file?.[0]?.originFileObj) {
          const file = values.file[0].originFileObj;
          const uploadRes = await fileApi.upload(file);
          fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
          fileName = uploadRes.data.data?.fileName || file.name;
        }
        await templatesApi.update(editing._id, {
          title: values.title,
          category: values.category || '',
          documentType: values.documentType || '',
          fileId, fileName,
          notes: values.notes || '',
        });
        message.success('تم تحديث القالب');
      } else {
        const file = values.file?.[0]?.originFileObj || values.file;
        if (!file) { message.error('يرجى اختيار ملف'); return; }
        const uploadRes = await fileApi.upload(file);
        const fileId = uploadRes.data.data?.fileId || uploadRes.data.fileId;
        const fileName = uploadRes.data.data?.fileName || file.name;
        await templatesApi.create({
          title: values.title,
          category: values.category || '',
          documentType: values.documentType || '',
          fileId, fileName,
          notes: values.notes || '',
        });
        message.success('تم رفع القالب');
      }

      setModalOpen(false);
      form.resetFields();
      fetchData();
    } catch (e: any) { if (!e?.errorFields) message.error('حدث خطأ'); }
    finally { setUploading(false); }
  };

  const handleDelete = async (id: string) => {
    try { await templatesApi.delete(id); message.success('تم الحذف'); fetchData(); }
    catch { message.error('حدث خطأ'); }
  };

  const handleOpen = (record: any) => {
    const url = fileApi.getUrl(record.fileId);
    if (window.electronAPI?.openFile) {
      window.electronAPI.openFile(url, record.title || 'معاينة المستند');
    } else {
      window.open(url, '_blank');
    }
  };

  const handlePrint = async (record: any) => {
    const url = fileApi.getUrl(record.fileId);
    setPrinting(true);
    try {
      if (window.electronAPI?.printFile) {
        const result = await window.electronAPI.printFile(url);
        if (!result.success) message.warning(result.message);
      } else {
        const printWin = window.open(url, '_blank');
        if (printWin) {
          setTimeout(() => { printWin.focus(); printWin.print(); }, 1000);
        }
      }
    } catch {
      message.error('تعذر الطباعة');
    } finally {
      setPrinting(false);
    }
  };

  const columns = [
    {
      title: 'اسم المستند', dataIndex: 'title', ellipsis: true,
      render: (text: string, r: any) => (
        <a onClick={() => handleOpen(r)} style={{ color: '#2c3e50', fontWeight: 500 }}>
          <FileTextOutlined style={{ marginLeft: 4, color: '#C9A227' }} />
          {text}
        </a>
      ),
    },
    { title: 'التصنيف', dataIndex: 'category', width: 120, ellipsis: true, render: (v: string) => v || '-' },
    {
      title: 'الصيغة', width: 80, align: 'center' as const,
      render: (_: any, r: any) => {
        const fmt = getFileFormat(r.fileName);
        return <Tag color={formatColor(fmt)} style={{ margin: 0 }}>{fmt}</Tag>;
      },
    },
    {
      title: 'الإجراءات', width: 240,
      render: (_: any, r: any) => (
        <Space size={4}>
          <Button type="text" size="small" icon={<EyeOutlined />} onClick={() => handleOpen(r)} title="فتح" style={{ color: '#2c3e50' }} />
          <Button type="text" size="small" icon={<DownloadOutlined />} href={fileApi.getUrl(r.fileId)} target="_blank" title="تحميل" style={{ color: '#2980b9' }} />
          <Button type="text" size="small" icon={<PrinterOutlined />} onClick={() => handlePrint(r)} title="طباعة" style={{ color: '#27ae60' }} />
          <Button type="text" size="small" icon={<EditOutlined />} onClick={() => openEdit(r)} title="تعديل" style={{ color: '#f39c12' }} />
          <Popconfirm title="حذف؟" onConfirm={() => handleDelete(r._id)}>
            <Button type="text" size="small" danger icon={<DeleteOutlined />} title="حذف" />
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <div>
      <PageHeader
        title="قوالب المستندات"
        subtitle="إدارة القوالب والمستندات الجاهزة"
        onAdd={openAdd}
        addLabel="رفع قالب"
      />

      {/* شريط البحث والفلترة */}
      <div style={{
        marginBottom: 12,
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        flexWrap: 'wrap',
      }}>
        <Input
          placeholder="بحث بالاسم..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          prefix={<SearchOutlined style={{ color: '#bfbfbf' }} />}
          allowClear
          style={{ maxWidth: 220 }}
        />
        <Select
          allowClear
          showSearch
          placeholder="التصنيف"
          optionFilterProp="children"
          value={categoryFilter}
          onChange={(val) => setCategoryFilter(val)}
          options={categoryOptions}
          suffixIcon={<FilterOutlined />}
          style={{ minWidth: 140 }}
        />
        <Select
          allowClear
          showSearch
          placeholder="الصيغة"
          optionFilterProp="children"
          value={formatFilter}
          onChange={(val) => setFormatFilter(val)}
          options={formatOptions}
          suffixIcon={<FilterOutlined />}
          style={{ minWidth: 120 }}
        />
      </div>

      <Table columns={columns} dataSource={filtered} rowKey="_id" loading={loading} size="small" pagination={{ pageSize: 10 }} />

      <AppModal
        title={editing ? 'تعديل قالب مستند' : 'رفع قالب مستند'}
        subtitle="أدخل بيانات المستند وارفع الملف"
        icon={<FolderOpenOutlined />}
        iconColor="#8e44ad"
        iconColorTo="#9b59b6"
        open={modalOpen}
        onOk={handleSubmit}
        onCancel={() => setModalOpen(false)}
        confirmLoading={uploading}
        okText={editing ? 'حفظ التعديلات' : 'رفع'}
        cancelText="إلغاء"
        okColor="#8e44ad"
        width={640}
      >

        <Form form={form} layout="vertical">
          {/* اختيار ملف */}
          <div style={{
            background: '#fafbfc',
            border: '1px dashed #d9d9d9',
            borderRadius: 10,
            padding: '12px 16px',
            marginBottom: 16,
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
              <PaperClipOutlined style={{ color: '#C9A227' }} />
              <span style={{ fontWeight: 600, fontSize: 13, color: '#2c3e50' }}>اختيار ملف</span>
              {editing && <span style={{ fontSize: 11, color: '#999' }}>(اتركه فارغاً للاحتفاظ بالملف الحالي)</span>}
              {!editing && <span style={{ fontSize: 11, color: '#999' }}>(PDF, Word, صور...)</span>}
            </div>
            <Form.Item
              name="file"
              rules={editing ? [] : [{ required: true, message: 'يرجى اختيار ملف' }]}
              valuePropName="fileList"
              getValueFromEvent={e => Array.isArray(e) ? e : e?.fileList}
              style={{ marginBottom: 0 }}
            >
              <Upload.Dragger beforeUpload={() => false} maxCount={1} style={{ background: 'transparent', borderColor: '#e0e0e0' }}>
                <p style={{ margin: 0, fontSize: 13, color: '#999' }}>
                  <UploadOutlined style={{ fontSize: 24, color: '#C9A227', marginBottom: 4 }} />
                  <br />
                  اضغط أو اسحب الملف هنا
                </p>
              </Upload.Dragger>
            </Form.Item>
          </div>

          {/* اسم المستند */}
          <Form.Item name="title" label="اسم المستند" rules={[{ required: true, message: 'يرجى إدخال اسم المستند' }]}>
            <Input placeholder="اسم المستند" prefix={<FileTextOutlined />} />
          </Form.Item>

          {/* التصنيف */}
          <Form.Item name="category" label="التصنيف">
            <Input placeholder="مثل: العقود / المذكرات / الدعاوى" />
          </Form.Item>

          {/* ملاحظات اختياري */}
          <Form.Item name="notes" label={<span>ملاحظات <span style={{ color: '#999', fontSize: 12 }}>(اختياري)</span></span>}>
            <Input.TextArea rows={2} placeholder="ملاحظات إضافية..." />
          </Form.Item>

        </Form>
      </AppModal>
    </div>
  );
}

import axios from 'axios';

const API_BASE_URL = 'http://localhost:3001/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// إرفاق token في كل طلب
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('lexpro_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// التعامل مع 401 (انتهاء الجلسة)
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('lexpro_token');
      localStorage.removeItem('lexpro_user');
      if (window.location.pathname !== '/login') {
        window.location.href = '/login';
      }
    }
    return Promise.reject(error);
  }
);

// مسارات الملفات
export const fileApi = {
  upload: (file: File) => {
    const formData = new FormData();
    formData.append('file', file);
    return api.post('/files/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
  },
  getUrl: (id: string) => `${API_BASE_URL}/files/${id}`,
};

// مسارات المصادقة
export const authApi = {
  login: (username: string, password: string) =>
    api.post('/auth/login', { username, password }),
  me: () => api.get('/auth/me'),
  updateProfile: (data: { name?: string; avatar?: string }) =>
    api.put('/auth/profile', data),
  changePassword: (currentPassword: string, newPassword: string) =>
    api.put('/auth/password', { currentPassword, newPassword }),
};

// مسارات المستخدمين
export const usersApi = {
  getAll: () => api.get('/users'),
  create: (data: any) => api.post('/users', data),
  update: (id: string, data: any) => api.put(`/users/${id}`, data),
  updatePermissions: (id: string, permissions: any[]) => api.put(`/users/${id}/permissions`, { permissions }),
  delete: (id: string) => api.delete(`/users/${id}`),
};

// مسارات سجل النشاط
export const activityApi = {
  getAll: () => api.get('/activity-logs'),
  markRead: () => api.put('/activity-logs/read'),
};

// مسارات الدردشة
export const chatApi = {
  getOnlineUsers: () => api.get('/auth/online-users'),
  getConversations: () => api.get('/messages/conversations'),
  getMessages: (userId: string) => api.get(`/messages/${userId}`),
  sendMessage: (receiverId: string, text: string) => api.post('/messages', { receiverId, text }),
};

// مسارات عامة CRUD
export function createCrudApi<T>(endpoint: string) {
  const path = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
  return {
    getAll: () => api.get(path),
    getById: (id: string) => api.get(`${path}/${id}`),
    create: (data: Partial<T>) => api.post(path, data),
    update: (id: string, data: Partial<T>) => api.put(`${path}/${id}`, data),
    delete: (id: string) => api.delete(`${path}/${id}`),
  };
}

export default api;

export {};

declare global {
  interface Window {
    electronAPI?: {
      savePDF: (html: string, fileName: string) => Promise<{ success: boolean; message: string }>;
      printDocument: (html: string) => Promise<{ success: boolean; message: string }>;
      printFile: (url: string) => Promise<{ success: boolean; message: string }>;
      openFile: (url: string, title: string) => Promise<{ success: boolean; message: string }>;
    };
  }
}

import { app, BrowserWindow, shell, ipcMain, dialog } from 'electron';
import * as path from 'path';
import * as fs from 'fs';

let mainWindow: BrowserWindow | null = null;

function createWindow(): void {
  mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 1024,
    minHeight: 700,
    show: false,
    title: 'LEX PRO - نظام إدارة مكاتب المحاماة',
    icon: path.join(__dirname, '..', '..', '..', 'build', 'icon.ico'),
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      preload: path.join(__dirname, 'preload.js'),
      zoomFactor: 0.95,
      plugins: true,
    },
  });

  // في وضع التطوير، حمّل من Vite dev server
  const isDev = !app.isPackaged;

  if (isDev) {
    mainWindow.loadURL('http://localhost:5173');
  } else {
    mainWindow.loadFile(path.join(__dirname, '../../renderer/dist/index.html'));
  }

  mainWindow.once('ready-to-show', () => {
    mainWindow?.show();
    mainWindow?.webContents.openDevTools();
  });

  // فتح الروابط الخارجية في المتصفح
  mainWindow.webContents.setWindowOpenHandler(({ url }: { url: string }) => {
    shell.openExternal(url);
    return { action: 'deny' as const };
  });

  mainWindow.on('closed', () => {
    mainWindow = null;
  });
}

// ============================================
// تصدير PDF وحفظه مباشرة على الجهاز
// ============================================
ipcMain.handle('save-pdf', async (event, html: string, fileName: string) => {
  try {
    const win = BrowserWindow.fromWebContents(event.sender);
    if (!win) return { success: false, message: 'لا توجد نافذة نشطة' };

    // إنشاء نافذة مخفية لعرض الـ HTML وتحويله إلى PDF
    const pdfWin = new BrowserWindow({
      show: false,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
      },
    });

    await pdfWin.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html));

    // انتظار تحميل المحتوى بالكامل
    await new Promise(resolve => setTimeout(resolve, 500));

    const pdfBuffer = await pdfWin.webContents.printToPDF({
      printBackground: true,
      pageSize: 'A4',
      landscape: false,
      margins: { marginType: 'custom', top: 0.4, bottom: 0.4, left: 0.4, right: 0.4 },
    });

    pdfWin.close();

    // فتح نافذة حفظ الملف
    const result = await dialog.showSaveDialog(win, {
      title: 'حفظ ملف PDF',
      defaultPath: fileName,
      filters: [{ name: 'PDF Files', extensions: ['pdf'] }],
    });

    if (result.canceled || !result.filePath) {
      return { success: false, message: 'تم إلغاء الحفظ' };
    }

    fs.writeFileSync(result.filePath, pdfBuffer);

    return { success: true, message: result.filePath };
  } catch (err) {
    return { success: false, message: (err as Error).message };
  }
});

// ============================================
// طباعة مع إظهار نافذة إعدادات الطباعة
// ============================================
ipcMain.handle('print-document', async (event, html: string) => {
  try {
    const win = BrowserWindow.fromWebContents(event.sender);
    if (!win) return { success: false, message: 'لا توجد نافذة نشطة' };

    const printWin = new BrowserWindow({
      show: true,
      width: 900,
      height: 700,
      title: 'معاينة الطباعة',
      parent: win,
      modal: true,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
      },
    });

    await printWin.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html));
    await new Promise(resolve => setTimeout(resolve, 500));

    printWin.focus();

    await printWin.webContents.print({ silent: false, printBackground: true });

    printWin.close();

    return { success: true, message: 'تمت الطباعة' };
  } catch (err) {
    return { success: false, message: (err as Error).message };
  }
});

// ============================================
// فتح ملف في نافذة مستقلة للمعاينة
// ============================================
ipcMain.handle('open-file', async (event, url: string, title: string) => {
  try {
    const win = BrowserWindow.fromWebContents(event.sender);
    if (!win) return { success: false, message: 'لا توجد نافذة نشطة' };

    const previewWin = new BrowserWindow({
      width: 1000,
      height: 800,
      title: title || 'معاينة المستند',
      parent: win,
      modal: false,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
        plugins: true,
      },
    });

    await previewWin.loadURL(url);
    previewWin.show();

    return { success: true, message: 'تم الفتح' };
  } catch (err) {
    return { success: false, message: (err as Error).message };
  }
});

// ============================================
// طباعة ملف من رابط مع إظهار نافذة الطباعة
// ============================================
ipcMain.handle('print-file', async (event, url: string) => {
  try {
    const win = BrowserWindow.fromWebContents(event.sender);
    if (!win) return { success: false, message: 'لا توجد نافذة نشطة' };

    const printWin = new BrowserWindow({
      show: false,
      parent: win,
      modal: true,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
        plugins: true,
      },
    });

    await printWin.loadURL(url);
    await new Promise(resolve => setTimeout(resolve, 2000));

    printWin.focus();

    await printWin.webContents.print({ silent: false, printBackground: true });

    printWin.close();

    return { success: true, message: 'تمت الطباعة' };
  } catch (err) {
    return { success: false, message: (err as Error).message };
  }
});

app.whenReady().then(() => {
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

import mongoose from 'mongoose';
import { deleteFile } from '../services/mega';

// ============================================
// نموذج المحامي (LawyerProfile)
// ============================================
const lawyerProfileSchema = new mongoose.Schema({
  name: { type: String, required: true },
  phone: { type: String, required: true },
  address: { type: String, required: true },
});

export const LawyerProfile = mongoose.model('LawyerProfile', lawyerProfileSchema);

// ============================================
// نموذج المحكمة (Court)
// ============================================
const courtSchema = new mongoose.Schema({
  name: { type: String, required: true },
});

export const Court = mongoose.model('Court', courtSchema);

// ============================================
// نموذج نوع القضية (CaseType)
// ============================================
const caseTypeSchema = new mongoose.Schema({
  name: { type: String, required: true },
});

export const CaseType = mongoose.model('CaseType', caseTypeSchema);

// ============================================
// نموذج نوع الإعلان (AnnouncementType)
// ============================================
const announcementTypeSchema = new mongoose.Schema({
  name: { type: String, required: true },
});

export const AnnouncementType = mongoose.model('AnnouncementType', announcementTypeSchema);

// ============================================
// نموذج العميل (Customer)
// ============================================
const customerSchema = new mongoose.Schema({
  name: { type: String, required: true },
  address: { type: String, default: '' },
  phone: { type: String, default: '' },
